style.css:
@-moz-document domain("youtube.com") {
/* 1. FONDO ROSA AURA CON CHIIKAWA INTEGRADO */
    ytd-app, 
    ytd-page-manager, 
    #page-manager, 
    #content, 
    #columns,
    #background,
    #masthead-container,
    tp-yt-app-drawer {
        background-color: #FFF0F5 !important; /* Rosa aura suave de base */
        background-image: url('https://ibb.co') !important; /* Tu Chiikawa tierno */
        background-attachment: fixed !important;
        background-size: cover !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
    }

    /* 2. TEXTOS DE LOS VIDEOS Y COMENTARIOS: Blanco Puro */
    #video-title, 
    #channel-name, 
    #content-text, 
    span, 
    a, 
    h1, 
    h2, 
    h3, 
    #title,
    #description-text,
    yt-formatted-string,
    .ytd-comment-renderer {
        color: #FFFFFF !important;
        text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.5) !important; /* Sombra negra para que el blanco sea legible */
    }

    /* 3. ICONOS GENERALES DE LA PÁGINA: Blanco Puro */
    svg, path, yt-icon {
        fill: #FFFFFF !important;
        color: #FFFFFF !important;
    }

    /* 4. BUSCADOR SUPERIOR: Amarillo Pollito */
    #search-form, 
    #container.ytd-searchbox, 
    input#search,
    .ytd-searchbox {
        background-color: #FFF59D !important; /* Fondo Amarillo Pollito */
        border: 2px solid #FF8AAB !important; /* Borde rosado estético */
        border-radius: 40px 0 0 40px !important;
    }
    /* El botón de la lupita de búsqueda */
    #search-icon-legacy, #search-icon-legacy yt-icon {
        background-color: #FFF59D !important;
        border: 2px solid #FF8AAB !important;
        border-radius: 0 40px 40px 0 !important;
    }
    /* La lupa dentro del buscador */
    #search-icon-legacy svg path {
        fill: #4A4A4A !important; /* Gris oscuro para que se note en el amarillo */
    }
    /* Texto que tú escribes al buscar */
    input#search {
        color: #4A4A4A !important;
    }

    /* 5. ICONOS DE LIKE, DISLIKE Y BOTÓN DE SUSCRIBIRSE: Amarillos */
    /* Botón Suscribirse */
    ytd-subscribe-button-renderer version-cards,
    #subscribe-button button,
    .ytd-subscribe-button-renderer {
        background-color: #FFF59D !important;
        color: #4A4A4A !important; /* Texto oscuro */
        font-weight: bold !important;
        border-radius: 20px !important;
    }
    /* Botones de Like y Dislike abajo del video */
    ytd-toggle-button-renderer yt-icon,
    #segmented-like-button yt-icon,
    #segmented-dislike-button yt-icon,
    .yt-spec-button-shape-next--segmented-start yt-icon {
        fill: #FFF59D !important;
        color: #FFF59D !important;
    }

    /* 6. MARCOS DE LÍNEAS ROSADAS ALREDEDOR DE LOS VIDEOS (INICIO) */
    ytd-rich-grid-media, 
    ytd-compact-video-renderer, 
    #dismissible.ytd-thumbnail {
        border: 3px dashed #FFB7CE !important; /* Marco con efecto de guiones/líneas rosadas */
        border-radius: 12px !important;
        padding: 8px !important;
        background-color: rgba(255, 240, 245, 0.4) !important; /* Fondo transparente rosa dentro del marco */
        box-shadow: 2px 2px 8px rgba(0,0,0,0.05) !important;
    }

    /* 7. BARRITA DE TIEMPO ROSADA CON STICKER DE MY MELODY */
    /* Línea del video reproduciéndose */
    .ytp-play-progress {
        background: #FF8AAB !important; /* Barra cargada en rosado */
    }
    /* Fondo de la línea que falta por cargar */
    .ytp-load-progress, .ytp-progress-list {
        background: rgba(255, 255, 255, 0.4) !important;
    }
    /* LA BOLITA DEL TIEMPO REEMPLAZADA POR MY MELODY */
    .ytp-scrubber-button {
        background: url('https://icons8.com') no-repeat center !important; /* Carita de Melody */
        background-size: contain !important;
        width: 28px !important;  /* Ajuste de tamaño para el sticker */
        height: 28px !important;
        border-radius: 0% !important; /* Elimina la bolita roja fea */
        box-shadow: none !important;
    }
}
